  "ui.wpAdminAgentFrameApp.feedback103": "เป้าหมายการอ่าน {value1} ไม่ได้รับอนุญาตในบริบทผู้ดูแล WordPress ปัจจุบัน ไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback104": "ยืนยันสิทธิ์ใหม่สำหรับโพสต์ WordPress {value1} ที่เลือกไว้อย่างชัดเจนไม่ได้ ไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback105": "โหลดเอกสาร Gutenberg ปัจจุบันได้ไม่ครบ ({value1}) ไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback106": "เอกสาร Gutenberg ปัจจุบันใช้ได้เฉพาะสแนปช็อตที่แบ่งเป็นส่วนและผูกไว้ ต้องอ่านทุกส่วนที่จำเป็นก่อนเตรียมแก้ไขทั้งเอกสาร ไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback107": "โพสต์ Gutenberg ปัจจุบันมีการแก้ไขที่ยังไม่บันทึก บันทึกหรืออัปเดตก่อนให้ Pixflow อ่านหรือเตรียมแก้ไขตามเนื้อหา ไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback108": "ยังไม่รองรับการล้างบล็อก Gutenberg ทั้งหมด Pixflow ไม่ได้ตีความคำขอนี้เป็นการแทนที่ด้วยเนื้อหาว่าง และไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback109": "Pixflow แยกไม่ได้ว่าข้อความนี้ตอบคำถามที่รออยู่หรือเริ่มคำขอใหม่ จึงไม่ได้เตรียมการตรวจทานและไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback110": "เอกสาร Gutenberg ปัจจุบันแบ่งเป็นส่วนและยังอ่านไม่ครบ Pixflow จึงเตรียมการตรวจทานทั้งเอกสารไม่ได้ ไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback111": "ไม่ได้ขอแทนที่เอกสาร Gutenberg ทั้งหมดอย่างชัดเจน Pixflow จึงปฏิเสธการแทนที่เอกสารปัจจุบัน ไม่มีการเปลี่ยนแปลง",
  "ui.wpAdminAgentFrameApp.feedback112": "Pixflow รีเฟรชสิทธิ์ออบเจ็กต์ WordPress หลังการกระทำก่อนหน้าไม่ได้ จะย้อนกลับการกระทำก่อนหน้า",
  "ui.wpAdminAgentFrameApp.feedback113": "โพสต์ที่จำเป็นไม่ได้สร้างด้วย ID WordPress ที่ถูกต้อง จะย้อนกลับการกระทำก่อนหน้า",
  "ui.wpAdminAgentFrameApp.feedback114": "Pixflow ยืนยันสิทธิ์ล่าสุดของโพสต์ที่สร้างใหม่ไม่ได้ จะย้อนกลับการกระทำก่อนหน้า",
