  "wp.message.47d932f4c02a": "สีตัวเลขที่ใช้งาน/เสร็จแล้ว",
  "wp.message.73dbcf028ec6": "เพิ่มวิธียืนยันที่สองเพื่อปกป้องบัญชีของคุณ",
  "wp.message.529da8588051": "ต้องยืนยันเพิ่มเติมเพื่อเข้าสู่ระบบให้เสร็จ",
  "wp.message.6b49000156c3": "ผู้ดูแลใช้การรีเซ็ตฉุกเฉินนี้ได้เมื่อผู้ใช้สูญเสียวิธียืนยันและรหัสกู้คืนทั้งหมด",
