  "wp.message.1be05927766c": "ผู้ดูแลนำการยืนยันสองขั้นตอนออกจากบัญชีของคุณ หากไม่ได้คาดหมายการเปลี่ยนแปลงนี้ ให้รีเซ็ตรหัสผ่านและติดต่อผู้ดูแลเว็บไซต์ทันที",
