  "wp.message.66d7671d170d": "ติดตั้งปลั๊กอิน Google Site Kit ล่าสุด แล้วตั้งค่าบริการเข้าสู่ระบบด้วย Google ที่:",
  "wp.message.793e6000d1b8": "ต้องยืนยันสองขั้นตอนแบบโต้ตอบ ใช้รหัสผ่านแอปพลิเคชัน WordPress เพื่อเข้าถึง API",
